var d=defs[Math.floor(rnd()*defs.length)],val=d.sp.lo+rnd()*(d.sp.hi-d.sp.lo),r={sensorId:d.id,type:d.sp.t,value:Math.round(val*10)/10,unit:d.sp.u,ts:Date.now()};
